    routes.sort(key=lambda r: len(r), reverse=True)
    merged_routes = []
    for route in routes:
        if not merged_routes:
            merged_routes.append(route)
            continue
        best_merge_index, best_merge_cost = None, float('inf')
        for i, merged_route in enumerate(merged_routes):
            candidate_route = merged_route + route[1:-1] + [merged_route[-1]]
            route_len, route_cost = evaluate_route(instance, candidate_route)
            if route_cost < best_merge_cost:
