    battery_usage = sum(state.battery_departure - state.battery_arrival for state in states)
    total_d = total_distance(instance, route)
    if total_d == 0:
        return float('inf')
    return battery_usage / total_d

def optimize_route(instance, route):
    # Implement a simple 2-opt heuristic to reorder customers
    n = len(route)
    if n <= 1:
        return route

    best_route = route.copy()
    improved = True

    while improved:
        improved = False
        for i in range(n - 1):
            for j in range(i + 1, n):
                candidate_route = route[:i] + route[i:j+1][::-1] + route[j+1:]
                if is_battery_feasible(instance, [route[0]] + candidate_route + [route[-1]]) and calculate_route_efficiency(instance, [route[0]] + candidate_route + [route[-1]]) < calculate_route_efficiency(instance, [route[0]] + best_route + [route[-1]]) and total_distance(instance, candidate_route) < total_distance(instance, best_route):
                    best_route = candidate_route
                    improved = True

    return best_route

def construct_route_with_energy_awareness(instance, unassigned_customers):
    depot = instance.depot_id
    route = [depot]
    while unassigned_customers:
        best_cid = None
        best_energy = float('inf')
        for cid in unassigned_customers:
            candidate_route = route + [cid, depot]
            states = propagate_route(instance, candidate_route)
            if all(state.battery_arrival >= 0 for state in states):
                energy_used = sum(energy_required(instance.node_map[route[i]], instance.node_map[route[i+1]], instance.vehicle) for i in range(len(route) - 1))
                if energy_used < best_energy:
                    best_cid = cid
                    best_energy = energy_used
        if best_cid:
            route = route + [best_cid, depot]
            unassigned_customers.remove(best_cid)
        else:
            break
    return route

def solve(instance, seed: int, time_limit_s: float):
    depot = instance.depot_id
    routes = []
    unassigned_customers = list(instance.customer_ids)

    while unassigned_customers:
        route = construct_route_with_energy_awareness(instance, unassigned_customers)
        if len(route) > 2:
            routes.append(route)
        else:
            # If no feasible route is found, try inserting a charging station
            for cid in unassigned_customers:
                candidate_route = route + [cid, depot]
                new_route = insert_charging_station(instance, candidate_route)
                if new_route:
                    routes.append(new_route)
                    unassigned_customers.remove(cid)
                    break
            else:
                # If still no feasible route, assign the customer to a new route
                routes.append([depot, cid, depot])
                unassigned_customers.remove(cid)

    # Attempt to merge routes to minimize the number of vehicles
    routes = merge_routes(instance, routes)

    # Further optimize routes by reordering customers
    routes = optimize_routes(instance, routes)

    return {"routes": routes, "metadata": {"seed": seed}}

